import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the pricing dependency (unit prices in euros).
const prices = { A: 10, B: 50, C: 0.1, D: 33.33, E: 110 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const totalFor = async (items) => (await (await post({ items })).json()).total

test('POST /orders 201 returns order with sequential string id, items and total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.match(res.headers.get('content-type'), /application\/json/)
  const body = await res.json()
  assert.deepEqual(body, { id: body.id, items: [{ sku: 'A', qty: 2 }], total: 20 })
  assert.equal(typeof body.id, 'string')
})

test('total: no discount at or below 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100) // exactly 100: not discounted
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }, { sku: 'B', qty: 1 }]), 80)
})

test('total: 10% discount above 100, floored', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99)   // 110 -> 99.0
  assert.equal(await totalFor([{ sku: 'B', qty: 4 }]), 180)   // 200 -> 180
  assert.equal(await totalFor([{ sku: 'A', qty: 101 }]), 909) // 1010 -> 909
})

test('total: fractional totals are floored, not rounded', async () => {
  assert.equal(await totalFor([{ sku: 'D', qty: 1 }]), 33)
  assert.equal(await totalFor([{ sku: 'D', qty: 4 }]), 119)   // 133.32 -> 119.988 -> 119
})

test('total: float error in the discount', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — total - total*0.1 uses binary floats,
  // so 110 becomes 98.99999999999999 and Math.floor yields 98 instead of 99 (see ledger below).
  assert.equal(await totalFor([{ sku: 'E', qty: 1 }]), 98)
})

test('total: a missing qty yields a null total (NaN serialised)', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no validation of items' sku/qty.
  const res = await post({ items: [{ sku: 'A' }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders 400 for missing, empty or invalid body', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post(null, 'not json')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/{id} 200 returns a stored order', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/{id} unknown id', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — unknown order answers 200, not 404.
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods answer 404', async () => {
  for (const [method, path] of [['GET', '/nope'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
cd .. && node --test 2>&1 | tail -25

